import numpy as np

def mse(y_true, y_pred):
    # gemiddelde van de gekwadrateerde fouten
    return np.mean((y_true - y_pred)**2)

def rmse(y_true, y_pred):
    # wortel van de mse — zelfde eenheid als de target
    return np.sqrt(mse(y_true, y_pred))

def mae(y_true, y_pred):
    # gemiddelde van de absolute fouten
    return np.mean(np.abs(y_true - y_pred))

# voorbeeldwaarden
y_true = np.array([3.0, -0.5, 2.0, 7.0])
y_pred = np.array([2.5,  0.0, 2.0, 8.0])

print('mse :', mse(y_true, y_pred))   # 0.375
print('rmse:', rmse(y_true, y_pred))  # 0.6123724356957945
print('mae :', mae(y_true, y_pred))   # 0.5
